from pathlib import Path

manager_path = Path("paper/src/main/java/net/enthusia/staff/paper/visibility/VanishManager.java")
manager = manager_path.read_text(encoding="utf-8")
needle = """    public boolean isVanished(UUID playerId) {\n        return visibility.isVanished(playerId);\n    }\n"""
replacement = needle + """\n    int vanishedOnlineCount() {\n        return (int) audiences.playerIds().stream()\n                .filter(this::isVanished)\n                .count();\n    }\n"""
if manager.count(needle) != 1:
    raise SystemExit("VanishManager isVanished insertion point changed")
if "int vanishedOnlineCount()" in manager:
    raise SystemExit("VanishManager online count accessor already exists")
manager_path.write_text(manager.replace(needle, replacement, 1), encoding="utf-8")

listener_path = Path("paper/src/main/java/net/enthusia/staff/paper/visibility/VanishBroadcastListener.java")
listener_path.write_text("""package net.enthusia.staff.paper.visibility;\n\nimport com.destroystokyo.paper.event.server.PaperServerListPingEvent;\nimport org.bukkit.event.EventHandler;\nimport org.bukkit.event.EventPriority;\nimport org.bukkit.event.Listener;\nimport org.bukkit.event.entity.PlayerDeathEvent;\nimport org.bukkit.event.player.PlayerAdvancementDoneEvent;\n\n/**\n * Removes vanished staff from public broadcast and server-list surfaces.\n */\npublic final class VanishBroadcastListener implements Listener {\n    private final VanishManager vanish;\n\n    public VanishBroadcastListener(VanishManager vanish) {\n        this.vanish = java.util.Objects.requireNonNull(vanish, \"vanish\");\n    }\n\n    @EventHandler(priority = EventPriority.HIGHEST)\n    public void onDeath(PlayerDeathEvent event) {\n        if (vanish.isVanished(event.getPlayer().getUniqueId())) {\n            event.deathMessage(null);\n        }\n    }\n\n    @EventHandler(priority = EventPriority.HIGHEST)\n    public void onAdvancement(PlayerAdvancementDoneEvent event) {\n        if (vanish.isVanished(event.getPlayer().getUniqueId())) {\n            event.message(null);\n        }\n    }\n\n    @EventHandler(priority = EventPriority.HIGHEST)\n    public void onPing(PaperServerListPingEvent event) {\n        event.getListedPlayers().removeIf(entry -> vanish.isVanished(entry.id()));\n        if (!event.shouldHidePlayers()) {\n            event.setNumPlayers(visibleCount(event.getNumPlayers(), vanish.vanishedOnlineCount()));\n        }\n    }\n\n    static int visibleCount(int reportedPlayers, int vanishedPlayers) {\n        return Math.max(0, reportedPlayers - Math.max(0, vanishedPlayers));\n    }\n}\n""", encoding="utf-8")

test_path = Path("paper/src/test/java/net/enthusia/staff/paper/visibility/VanishBroadcastListenerTest.java")
test_path.write_text("""package net.enthusia.staff.paper.visibility;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport org.junit.jupiter.api.Test;\n\nclass VanishBroadcastListenerTest {\n    private static final Path SOURCE = Path.of(\n            \"src/main/java/net/enthusia/staff/paper/visibility/VanishBroadcastListener.java\"\n    );\n    private static final Path MANAGER_SOURCE = Path.of(\n            \"src/main/java/net/enthusia/staff/paper/visibility/VanishManager.java\"\n    );\n\n    @Test\n    void vanishedPlayersAreRemovedFromAdvertisedCountWithoutGoingNegative() {\n        assertEquals(7, VanishBroadcastListener.visibleCount(10, 3));\n        assertEquals(0, VanishBroadcastListener.visibleCount(1, 4));\n        assertEquals(5, VanishBroadcastListener.visibleCount(5, -1));\n    }\n\n    @Test\n    void pingFilteringAvoidsDeprecatedOrCrossThreadRosterIteration() throws IOException {\n        String source = Files.readString(SOURCE);\n        String manager = Files.readString(MANAGER_SOURCE);\n\n        assertTrue(source.contains(\"event.getListedPlayers().removeIf\"));\n        assertTrue(source.contains(\"vanish.vanishedOnlineCount()\"));\n        assertFalse(source.contains(\"event.iterator()\"));\n        assertFalse(source.contains(\"getServer().getOnlinePlayers()\"));\n        assertTrue(manager.contains(\"audiences.playerIds().stream()\"));\n        assertTrue(manager.contains(\".filter(this::isVanished)\"));\n    }\n}\n""", encoding="utf-8")
